prompt --application/shared_components/plugins/region_type/apex_qr_code_scanner
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(32116185373588460160)
,p_plugin_type=>'REGION TYPE'
,p_name=>'APEX.QR.CODE.SCANNER'
,p_display_name=>'APEX QR Code Scanner'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','APEX.QR.CODE.SCANNER'),'')
,p_javascript_file_urls=>'#PLUGIN_FILES#qrsc.pkgd.min.js'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function f_render (',
'    p_region              in apex_plugin.t_region,',
'    p_plugin              in apex_plugin.t_plugin,',
'    p_is_printer_friendly in boolean',
') return apex_plugin.t_region_render_result is',
'begin',
'',
'    apex_javascript.add_onload_code(''qrCodeScanner(apex, $, Html5Qrcode, Html5QrcodeSupportedFormats).initialize( {'' ||',
'        apex_javascript.add_attribute(p_name => ''regionID'', p_value => p_region.static_id, p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''height'', p_value => p_region.attribute_06, p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''resultMode'', p_value => to_number(p_region.attribute_02), p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''executeJavaScript'', p_value => p_region.attribute_03, p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''setItem'', p_value => p_region.attribute_04, p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''disableNumberConversion'', p_value => case when p_region.attribute_05 = ''Y'' then true else false end, p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''mirrorCamera'', p_value => case when p_region.attribute_08 = ''Y'' then true else false end, p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''scanFormats'', p_value => p_region.attribute_07, p_add_comma => true ) ||',
'        apex_javascript.add_attribute(p_name => ''facingMode'', p_value => p_region.attribute_09, p_add_comma => false ) ||',
'    ''} );'');',
'',
'    return null;',
'end;'))
,p_api_version=>1
,p_render_function=>'F_RENDER'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This Region Plug-in is used to scan codes. If any string has been detected an APEX Item can be set, Dynamic Action can be fired or JavaScript can be executed.</p>',
'<p>The following formats are supported: QR_CODE, AZTEC, CODABAR, CODE_39, CODE_93, CODE_128, DATA_MATRIX, MAXICODE, ITF, EAN_13, EAN_8, PDF_417, RSS_14, RSS_EXPANDED, UPC_A, UPC_E, UPC_EAN_EXTENSION</p>',
'<p>To control the QR Code Scanner you can fire events on th QR Code region. The following events are supportet:</p>',
'<ul>',
'<li>apex.region("region_id").pause(); => stop Scanner Video</li>',
'<li>apex.region("region_id").start(); => start Scanner video</li>',
'<li>apex.region("region_id").refresh(); => reset the currentValue and the item</li>',
'<li>apex.region("region_id").setFacingMode(); => change camera</li>',
'</ul>'))
,p_version_identifier=>'22.12.15'
,p_about_url=>'https://github.com/RonnyWeiss/APEX-QR-Code-Scanner'
,p_files_version=>1227
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(32122563598452918607)
,p_plugin_id=>wwv_flow_imp.id(32116185373588460160)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Set Mode'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'2'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Used to select what''s happening when qr had been detected. You can choose the execution of JavaScript or you can set an APEX Item.'
);
