 p_id=>wwv_flow_imp.id(98698611782058750)
,p_plug_name=>'LOGIN'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(191837119796163983)
,p_plug_display_sequence=>20
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!doctype html>',
'<html lang="en">',
'<head>',
'  <meta charset="utf-8" />',
'  <meta name="viewport" content="width=device-width,initial-scale=1" />',
'  <title>Premium Animated Login</title>',
'  <meta name="description" content="Highly attractive custom login page for Oracle APEX" />',
'',
'  <style>',
'    @import url(''https://fonts.googleapis.com/css2?family=Poppins:wght@400;600&display=swap'');',
'    :root{',
'      --bg1:#0f1724;',
'      --bg2:#1e293b;',
'      --accent:#4f7cff;',
'      --accent2:#64b5ff;',
'      --card:rgba(255,255,255,0.05);',
'      --glass:rgba(255,255,255,0.08);',
'      --radius:14px;',
'      --text-light:#fff;',
'      --text-muted:rgba(255,255,255,0.7);',
'    }',
'',
'    *{margin:0;padding:0;box-sizing:border-box;}',
'    html,body{height:100%; font-family:''Poppins'',sans-serif; display:flex; justify-content:center; align-items:center; background: linear-gradient(135deg,var(--bg1),var(--bg2));}',
'',
'    body::before{content:'''';position:fixed;inset:0;background: radial-gradient(circle at 20% 30%, rgba(79,124,255,0.12), transparent 30%), radial-gradient(circle at 80% 70%, rgba(100,181,255,0.1), transparent 40%); animation:bgMove 25s linear infinit'
||'e; z-index:0;}',
'    @keyframes bgMove{0%{transform:translate(0,0);}50%{transform:translate(50px,-30px);}100%{transform:translate(0,0);}}',
'',
'    .card{position:relative; z-index:1; width:380px; padding:36px; border-radius:var(--radius); background:var(--card); backdrop-filter:blur(10px); box-shadow:0 10px 40px rgba(0,0,0,0.6); border:1px solid var(--glass); animation:cardPop 1s ease;}',
'    @keyframes cardPop{0%{opacity:0; transform:translateY(40px) scale(0.95);}100%{opacity:1; transform:translateY(0) scale(1);}}',
'',
'    .brand{display:flex; align-items:center; gap:14px; margin-bottom:28px;}',
'    .logo{width:60px; height:60px; background: linear-gradient(145deg,var(--accent),var(--accent2)); border-radius:16px; display:grid; place-items:center; box-shadow: 0 4px 20px rgba(79,124,255,0.3);}',
'    .brand h1{color:var(--text-light); font-size:22px;}',
'    .brand p{color:var(--text-muted); font-size:14px;}',
'',
'    form{display:flex; flex-direction:column; gap:16px;}',
'    .field{position:relative;}',
'    input{width:100%; padding:16px; border-radius:12px; border:none; background:rgba(255,255,255,0.06); color:var(--text-light); font-size:15px; outline:none; transition:0.3s;}',
'    input:focus{background:rgba(79,124,255,0.1); box-shadow:0 0 12px rgba(79,124,255,0.3);}',
'    label{position:absolute; left:16px; top:50%; transform:translateY(-50%); color:var(--text-muted); pointer-events:none; transition:0.3s;}',
'    input:focus + label, input:not(:placeholder-shown) + label{top:-10px; font-size:12px; color:var(--accent);}',
'',
'    .actions{display:flex; justify-content:space-between; align-items:center;}',
'    .checkbox{display:flex; align-items:center; gap:8px; color:var(--text-muted); font-size:13px;}',
'',
'    .btn{padding:14px; border:none; border-radius:12px; background: linear-gradient(90deg,var(--accent),var(--accent2)); color:var(--text-light); font-weight:600; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:10px; tra'
||'nsition:0.3s; font-size:15px;}',
'    .btn:hover{transform:translateY(-2px); box-shadow:0 8px 24px rgba(79,124,255,0.4);}',
'',
'    .link{color:var(--text-muted); font-size:13px; text-decoration:none;}',
'    .link:hover{color:var(--text-light);}',
'',
'    .foot{text-align:center; font-size:12px; color:var(--text-muted); margin-top:14px;}',
'',
'    .divider{height:1px; background: linear-gradient(to right,transparent,rgba(255,255,255,0.1),transparent); margin:12px 0;}',
'  </style>',
'</head>',
'<body>',
'',
'<div class="card">',
'  <header class="brand">',
unistr('    <div class="logo">\D83D\DC8E</div>'),
'    <div>',
'      <h1>Welcome Back</h1>',
'      <p>Sign in to your account</p>',
'    </div>',
'  </header>',
'',
'  <form id="loginForm" autocomplete="on">',
'    <div class="field">',
'      <input type="text" id="P1_USERNAME" placeholder=" " required autocomplete="username">',
'      <label>Username or Email</label>',
'    </div>',
'    <div class="field">',
'      <input type="password" id="P1_PASSWORD" placeholder=" " required autocomplete="current-password">',
'      <label>Password</label>',
'    </div>',
'',
'    <div class="actions">',
'      <label class="checkbox"><input type="checkbox" /> Remember me</label>',
'      <a href="#" class="link">Forgot?</a>',
'    </div>',
'',
'    <button type="button" class="btn" id="btnLogin">Sign In</button>',
'',
'    <div class="divider"></div>',
'    <div class="foot">Don''t have an account? <a href="#" class="link">Request access</a></div>',
'  </form>',
'</div>',
'',
'<script>',
'document.getElementById(''btnLogin'').addEventListener(''click'', function(){',
'  var username = document.getElementById(''P1_USERNAME'').value;',
'  var password = document.getElementById(''P1_PASSWORD'').value;',
'  if(!username || !password){alert(''Enter username and password''); return;}',
'  $s(''P1_USERNAME'', username); $s(''P1_PASSWORD'', password);',
'  apex.submit(''LOGIN'');',
'});',
'</script>',
'',
'</body>',
'</html>',
''))
,p_required_patch=>wwv_flow_imp.id(191724404433163656)
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
