'    <!-- Bottom Settings -->',
'    <div>',
unistr('      <a href="f?p=&APP_ID.:10000:&SESSION." style="color:#fff;text-decoration:none;">\2699 Settings</a>'),
'    </div>',
'  </aside>',
'',
'  <!-- Main Content -->',
'  <main style="flex:1;padding:20px;overflow:auto;background:linear-gradient(135deg,#1e293b,#0f1724);color:#fff;">',
'    ',
'    <!-- Topbar -->',
'    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:25px;">',
'      <div style="font-size:18px;font-weight:600;">Welcome, &APP_USER.</div>',
unistr('      <div>\D83D\DD14 Notifications</div>'),
'    </div>',
'',
'    <!-- Cards Section -->',
'    <div style="display:flex;gap:20px;margin-bottom:30px;" id="cardsSection">',
'      <div class="card" id="cardTotalBarcodes" style="flex:1;padding:20px;background:rgba(255,255,255,0.05);border-radius:12px;box-shadow:0 8px 20px rgba(79,124,255,0.3);transition:0.3s;">',
'        Total Admin User<br>',
'        <span style="font-size:24px;font-weight:700;">&P1_ADMIN_USERS.</span>',
'      </div>',
'      <div class="card" id="cardActiveUsers" style="flex:1;padding:20px;background:rgba(255,255,255,0.05);border-radius:12px;box-shadow:0 8px 20px rgba(79,124,255,0.3);transition:0.3s;">',
'        Active Users<br>',
'        <span style="font-size:24px;font-weight:700;">&P1_ACTIVE.</span>',
'      </div>',
'      <div class="card" id="cardPendingApproval" style="flex:1;padding:20px;background:rgba(255,255,255,0.05);border-radius:12px;box-shadow:0 8px 20px rgba(79,124,255,0.3);transition:0.3s;">',
'        In Active<br>',
'        <span style="font-size:24px;font-weight:700;">&P1_LOCKED.</span>',
'      </div>',
'    </div>',
'',
'    <!-- Single Yes/No Switch -->',
'    <div class="switch-container">',
'      <label class="switch">',
'        <input type="checkbox" id="singleYesNoSwitch">',
'        <span class="slider round"></span>',
'      </label>',
'      <span id="switchValueSingle"></span>',
'    </div>',
'',
'    <!-- Charts Section --> ',
'    <div style="display:flex;gap:20px;margin-top:20px;margin-bottom:30px;">',
'      <div id="chartBarcodes" style="flex:1;height:300px;background:rgba(255,255,255,0.05);border-radius:12px;padding:10px;"></div>',
'      <div id="chartUsers" style="flex:1;height:300px;background:rgba(255,255,255,0.05);border-radius:12px;padding:10px;"></div>',
'    </div>',
'',
'    <!-- Recent Activity Table -->',
'    <div style="background:rgba(255,255,255,0.05);padding:20px;border-radius:12px;">',
'      <h3 style="margin-bottom:15px;">Recent Activity</h3>',
'      <table id="tblRecentActivity" style="width:100%;border-collapse:collapse;">',
'        <thead>',
'          <tr style="border-bottom:1px solid rgba(255,255,255,0.2);">',
'            <th style="padding:10px;text-align:left;">Barcode</th>',
'            <th style="padding:10px;text-align:left;">User</th>',
'            <th style="padding:10px;text-align:left;">Status</th>',
'            <th style="padding:10px;text-align:left;">Time</th>',
'          </tr>',
'        </thead>',
'        <tbody></tbody>',
'      </table>',
'    </div>',
'',
'  </main>',
'</div>',
'',
'<style>',
'.switch-container {',
'  display: flex;',
'  align-items: center;',
'  gap: 10px;',
'  margin-top: 15px;',
'  font-size: 16px;',
'}',
'.switch {',
'  position: relative;',
'  display: inline-block;',
'  width: 50px;',
'  height: 26px;',
'}',
'.switch input {',
'  opacity: 0;',
'  width: 0;',
'  height: 0;',
'}',
'.slider {',
'  position: absolute;',
'  cursor: pointer;',
'  top: 0; left: 0; right: 0; bottom: 0;',
'  background-color: #ccc;',
'  transition: 0.4s;',
'  border-radius: 34px;',
'}',
'.slider:before {',
'  position: absolute;',
'  content: "";',
'  height: 20px; width: 20px;',
'  left: 3px; bottom: 3px;',
'  background-color: white;',
'  transition: 0.4s;',
'  border-radius: 50%;',
'}',
'input:checked + .slider {',
'  background-color: #4f7cff;',
'}',
'input:checked + .slider:before {',
'  transform: translateX(24px);',
'}',
'</style>',
'',
'<script src="https://cdn.jsdelivr.net/npm/apexcharts"></script>',
'',
'<script>',
'document.addEventListener("DOMContentLoaded", function(){',
'',
'  // -----------------------------',
'  // Dashboard Metrics',
'  // -----------------------------',
'  apex.server.process("GET_DASHBOARD_METRICS", {}, {',
'    success: function(data){',
'      document.querySelector("#cardTotalBarcodes span").innerText = data.total_barcodes;',
'      document.querySelector("#cardActiveUsers span").innerText = data.active_users;',
'      document.querySelector("#cardPendingApproval span").innerText = data.pending_approval;',
'    }',
'  });',
'',
'  // Barcode Trends Chart',
'  apex.server.process("GET_BARCODE_TRENDS", {}, {',
'    success: function(data){',
'      var options = { chart:{type:''line'',height:300}, series:[{name:''Barcodes'',data:data.values}], xaxis:{categories:data.labels}, colors:[''#4f7cff'']};',
'      new ApexCharts(document.querySelector("#chartBarcodes"), options).render();',
'    }',
'  });',
'',
'  // Active Users Chart',
'  apex.server.process("GET_USER_TRENDS", {}, {',
'    success: function(data){',
'      var options = { chart:{type:''area'',height:300}, series:[{name:''Users'',data:data.values}], xaxis:{categories:data.labels}, colors:[''#64b5ff'']};',
'      new ApexCharts(document.querySelector("#chartUsers"), options).render();',
'    }',
'  });',
'',
'  // Recent Activity Table',
'  apex.server.process("GET_RECENT_ACTIVITY", {}, {',
'    success: function(data){',
'      const tbody = document.querySelector("#tblRecentActivity tbody");',
'      tbody.innerHTML = '''';',
'      data.forEach(function(row){',
'        tbody.innerHTML += `<tr>',
'          <td style="padding:10px;">${row.barcode}</td>',
'          <td style="padding:10px;">${row.username}</td>',
'          <td style="padding:10px;">${row.status}</td>',
'          <td style="padding:10px;">${row.time}</td>',
'        </tr>`;',
'      });',
'    }',
'  });',
'',
'  // -----------------------------',
'  // Single Yes/No Switch',
'  // -----------------------------',
'  const switchEl = document.getElementById("singleYesNoSwitch");',
'  const switchValue = document.getElementById("switchValueSingle");',
'',
'  // Initialize switch from P1_SET value',
'  let initialVal = "&P1_SET."; // APEX substitution',
'  initialVal = initialVal.trim();',
'  if(initialVal === "Yes"){',
'    switchEl.checked = true;',
'    switchValue.innerText = "Yes";',
'  } else {',
'    switchEl.checked = false;',
'    switchValue.innerText = "No";',
'  }',
'',
'  // Change event',
'  switchEl.addEventListener("change", function() {',
'    const val = this.checked ? "Yes" : "No";',
'    switchValue.innerText = val;',
'',
'    // Update APEX page item (client-side)',
'    if(typeof apex !== "undefined"){',
'      apex.item("P1_SET").setValue(val, true); // true prevents recursion',
'    }',
'  });',
'',
'});',
'</script>',
''))
,p_required_patch=>wwv_flow_imp.id(191724404433163656)
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
