'  lineChart.setOption(lineOption);',
'',
'  // ----- (optional) other simple charts just as placeholders -----',
'  barChart.setOption({',
'    title: { text: ''Bar (placeholder)'', left: ''center'' },',
'    tooltip: {},',
'    xAxis: { type: ''category'', data: categories },',
