wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(166125336301553013)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_DEEPSEEK_RESPONSE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_response CLOB;',
'    l_text     CLOB;',
'    l_prompt   VARCHAR2(4000) := apex_application.g_x01;',
'    l_body     CLOB;',
'BEGIN',
'    IF l_prompt IS NOT NULL THEN',
'',
'        SELECT json_object(',
'            ''model'' VALUE ''deepseek-chat'',',
'            ''messages'' VALUE json_array(',
'                json_object(',
'                    ''role'' VALUE ''user'',',
'                    ''content'' VALUE l_prompt',
'                )',
'            )',
'        )',
'        INTO l_body',
'        FROM dual;',
'',
'        l_response := apex_web_service.make_rest_request(',
'            p_url                 => ''https://api.deepseek.com/v1/chat/completions'',',
'            p_http_method         => ''POST'',',
'            p_body                => l_body,',
'            p_credential_static_id => ''DEEPSEEK_API''',
'        );',
'',
'        l_text := json_value(l_response FORMAT JSON, ''$.choices[0].message.content'');',
'',
'        apex_json.open_object;',
'        apex_json.write(''success'', true);',
'        apex_json.write(''response'', l_text);',
'        apex_json.close_object;',
'',
'    ELSE',
'        apex_json.open_object;',
'        apex_json.write(''success'', false);',
'        apex_json.write(''error'', ''No prompt provided'');',
'        apex_json.close_object;',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''success'', false);',
'        apex_json.write(''error'', SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>166125336301553013
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(194359441803773633)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_BAR_DATA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
' APEX_JSON.OPEN_ARRAY;',
' FOR rec IN (',
' SELECT product_name, SUM(quantity) AS total_qty',
' FROM order_items',
' WHERE ( :P2_PRODUCT_NAME IS NULL OR product_name = :P2_PRODUCT_NAME )',
' AND ( :P2_ORDER_ID IS NULL OR order_id = :P2_ORDER_ID )',
' GROUP BY product_name',
' ORDER BY product_name',
' ) LOOP',
' APEX_JSON.OPEN_OBJECT;',
' APEX_JSON.WRITE(''PRODUCT_NAME'', rec.product_name);',
' APEX_JSON.WRITE(''TOTAL_QTY'', rec.total_qty);',
' APEX_JSON.CLOSE_OBJECT;',
'  END LOOP;',
' APEX_JSON.CLOSE_ARRAY;',
'END;',
'',
'',
'-- BEGIN',
'--   -- Generate JSON array',
'--   APEX_JSON.OPEN_ARRAY;',
'',
'--   FOR rec IN (',
'--     SELECT product_name, SUM(quantity) AS total_qty',
'--     FROM order_items',
'--     WHERE (:P2_PRODUCT_NAME IS NULL OR product_name = :P2_PRODUCT_NAME)',
'--       AND (:P2_ORDER_ID IS NULL OR order_id = :P2_ORDER_ID)',
'--     GROUP BY product_name',
'--     ORDER BY product_name',
'--   ) LOOP',
'--     APEX_JSON.OPEN_OBJECT;',
'--     APEX_JSON.WRITE(''PRODUCT_NAME'', rec.product_name);',
'--     APEX_JSON.WRITE(''TOTAL_QTY'', rec.total_qty);',
'--     APEX_JSON.CLOSE_OBJECT;',
'--   END LOOP;',
'',
'--   APEX_JSON.CLOSE_ARRAY;',
'',
'--   -- Return JSON as HTTP response',
'--   OWA_UTIL.mime_header(''application/json'', FALSE);',
'--   HTP.p(APEX_JSON.GET_CLOB_OUTPUT);',
'--   OWA_UTIL.http_header_close;',
'-- END;',
''))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(191724404433163656)
,p_internal_uid=>96898165491767220
);
end;
