'    var colId = $(this).attr("id");',
'    var colText = $(this).text().trim().toLowerCase(); // ALWAYS lowercase',
'    var hasValue = false;',
'',
unistr('    // --- \2714 Skip Edit column (never hide) ---'),
'    if (colText === "edit" || colText === "update" || colText === "action") {',
'        return; ',
'    }',
'',
'    // Check ALL body tables',
'    tables.each(function() {',
'        $(this).find("td[headers*=''" + colId + "'']").each(function() {',
'            if ($(this).text().trim() !== "") {',
'                hasValue = true;',
'                return false; ',
'            }',
'        });',
'    });',
'',
'    // Hide or show column',
'    if (!hasValue) {',
'        tables.each(function() {',
'            $(this).find("th#" + colId).hide();',
'            $(this).find("td[headers*=''" + colId + "'']").hide();',
'        });',
'    } else {',
'        tables.each(function() {',
'            $(this).find("th#" + colId).show();',
'            $(this).find("td[headers*=''" + colId + "'']").show();',
'        });',
'    }',
'});',
'',
'',
