wwv_flow_imp_page.create_page(
 p_id=>3
,p_name=>'BAR CODE SCANNING'
,p_alias=>'BAR-CODE-SCANNING'
,p_step_title=>'BAR CODE SCANNING'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'',
'(function($){',
'  $(function(){',
'',
'    // Replace with your IG''s actual static id (without #)',
'    var igStaticId = "ig_static_id"; ',
'',
'    $("#" + igStaticId).on("interactivegridviewmodelcreate", function(event, ui){',
'      if (ui.viewId !== "grid") return;',
'',
'      var model = ui.model;',
'',
'      // Function to update totals',
'      function updateTotals() {',
'        var totalQuantity = 0;',
'        var rollCount     = 0;  // Variable to count non-empty Roll_No',
'        var totalWeight   = 0;',
'',
'        var colQty    = model.getFieldKey("QTY_PACK_PL");',
'        var colRoll   = model.getFieldKey("PACK_NO_PL");',
'',
'        var recordCount = 0;',
'',
'        // Loop through all records in the Interactive Grid',
'        model.forEach(function(rec, i, id){',
'          var meta = model.getRecordMetadata(id);',
'          if (meta.deleted || meta.agg) return;',
'          recordCount++;',
'',
'          var qty   = parseFloat(rec[colQty]);',
'          var roll  = rec[colRoll];  // Roll_No could be any data type, check its content',
'',
'          // Calculate totals for quantity',
'          if (!isNaN(qty))    totalQuantity += qty;',
'',
'          // Count Roll_No entries (non-empty and non-null)',
'          if (roll && roll.trim() !== "") {',
'            rollCount++;  // Increment if Roll_No is not empty or null',
'          }',
'        });',
'',
'        // Calculate Estimated Weight based on total Quantity',
'        // You can replace this logic if you have a custom weight per quantity',
'        var estimatedWeight = totalQuantity * 1;  // Assuming 1 is weight per unit (modify as per your requirement)',
'',
'        // Reset totals if no records found',
'        if (recordCount === 0) {',
'          totalQuantity = 0;',
'          rollCount     = 0;',
'          totalWeight   = 0;',
'          estimatedWeight = 0;',
'        }',
'',
'        // Use apex.item API to set values for page items',
'        try {',
'          apex.item("P3_TOTAL_QUANTITY").setValue(totalQuantity);',
'          apex.item("P3_TOTAL_ROLL_NO").setValue(rollCount);  // Set Roll_No count',
'          apex.item("P3_TOTAL_WEIGHT").setValue(estimatedWeight);  // Set Estimated Weight as Total Weight',
'        } catch(e) {',
'          console.log("Error setting page items:", e);',
'        }',
'',
'        // Debug output',
'        console.log("Totals updated:", {',
'          records: recordCount,',
'          totalQuantity: totalQuantity,',
'          totalRollNoCount: rollCount,',
'          totalWeight: estimatedWeight  // Set Estimated Weight as Total Weight',
'        });',
'      }',
'',
'      // Subscribe to model change events to update totals on changes',
'      model.subscribe({',
'        onChange: function(type, change){',
'          if (',
'            (type === "set" && (change.field === "QTY_PACK_PL" || change.field === "PACK_NO_PL")) ||',
'            type === "insert" ||',
'            type === "delete"',
'          ) {',
'            updateTotals();',
'          }',
'        }',
'      });',
'',
'      // Initial calculation after grid load',
'      model.fetchAll(function(){',
'        updateTotals();',
'      });',
'',
'      // Recalculate totals when IG is refreshed',
'      apex.region(igStaticId).widget().on("apexafterrefresh", function(){',
'        updateTotals();',
'      });',
'',
'    });',
'',
'  });',
'})(apex.jQuery);',
''))
