'DECLARE',
'    v_rec apps.Q_PACKING_LIST_FABRIC_ISSUE__V@proddb%ROWTYPE;',
'BEGIN',
'    -- 1) Fetch full record from source view',
'    BEGIN',
'        SELECT *',
'        INTO   v_rec',
'        FROM   apps.Q_PACKING_LIST_FABRIC_ISSUE__V@proddb',
'        WHERE  BAR_CODE_PL = :P3_BAR_CODE;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            -- APEX_ERROR.ADD_ERROR(',
'            --     p_message => ''Barcode not found!'',',
'            --     p_display_location => apex_error.c_inline_in_notification',
'            -- );',
'            null;',
'            RETURN;',
'    END;',
'',
'',
'       INSERT INTO MTML_BAR_CODE_TRX_M1_LINE',
'        (TRX_NO,PLAN_ID,PLAN_NAME,OCCURRENCE,ORDER_NO_PL,ITEM_CODE_PL,SET_NO_PL,BAR_CODE_PL,JOB_NO_PL,',
'         PACK_TYPE_PL,PACK_NO_PL,QTY_PACK_PL,NO_PIECES_PL,DEMAND_NO_PL)',
'    VALUES',
'        (:P3_TRX_NO, v_rec.PLAN_ID,v_rec.PLAN_NAME,v_rec.OCCURRENCE,v_rec.ORDER_NO_PL,',
'         v_rec.ITEM_CODE_PL,v_rec.SET_NO_PL, v_rec.BAR_CODE_PL,v_rec.JOB_NO_PL,v_rec.PACK_TYPE_PL,v_rec.PACK_NO_PL,v_rec.QTY_PACK_PL,',
'         v_rec.NO_PIECES_PL,v_rec.DEMAND_NO_PL);',
'',
'EXCEPTION',
'    WHEN DUP_VAL_ON_INDEX THEN',
'        APEX_ERROR.ADD_ERROR(',
'            p_message => ''Barcode already scanned!'',',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>98365205095090910
);
