,p_process_name=>'deleteALl'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
unistr('   --\067E\06C1\0644\06D2 detail records delete \06A9\0631\06CC\06BA'),
'   DELETE FROM MTML_BAR_CODE_TRX_M1_LINE',
'   WHERE TRX_NO = :P3_TRX_NO;',
'',
'   --Check if any records were deleted in the detail table',
'   IF SQL%ROWCOUNT = 0 THEN',
'      --If no rows were deleted, redirect to Page 2',
'      APEX_UTIL.REDIRECT_URL(''f?p=&APP_ID.:2:&SESSION.'');',
'      RETURN;  -- This stops the execution here',
'   END IF;',
'',
unistr('   --\067E\06BE\0631 master record delete \06A9\0631\06CC\06BA'),
'   DELETE FROM MTML_BAR_CODE_TRX_M1_HEAD',
'   WHERE TRX_NO = :P3_TRX_NO;',
'',
'   --Check if any records were deleted in the master table',
'   IF SQL%ROWCOUNT = 0 THEN',
'      -- If no rows were deleted, redirect to Page 2',
'      APEX_UTIL.REDIRECT_URL(''f?p=&APP_ID.:2:&SESSION.'');',
'      RETURN;  -- This stops the execution here',
'   END IF;',
'',
'   COMMIT;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      -- Rollback on any exception',
'     NULL;',
'      -- Optionally, re-raise the error or handle it',
'      RAISE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'HAVE SOMETING ERROR..'
