,p_page_mode=>'MODAL'
,p_step_title=>'Generate Barcode'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
,p_last_updated_by=>'AMIR'
,p_last_upd_yyyymmddhh24miss=>'20251126093139'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(98365567080090913)
,p_plug_name=>'Duplicate Barcode'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--hideHeader:t-Region--noUI:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(191837119796163983)
,p_plug_display_sequence=>10
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'    v_barcode_list SYS.ODCIVARCHAR2LIST := SYS.ODCIVARCHAR2LIST(',
'        :P4_BAR_CODE_1,',
'        :P4_BAR_CODE_2,',
'        :P4_BAR_CODE_3,',
'        :P4_BAR_CODE_4,',
'        :P4_BAR_CODE_5,',
'        :P4_BAR_CODE_6,',
'        :P4_BAR_CODE_7,',
'        :P4_BAR_CODE_8,',
'        :P4_BAR_CODE_9,',
'        :P4_BAR_CODE_10,',
'        :P4_BAR_CODE_11,',
'        :P4_BAR_CODE_12',
'    );',
'BEGIN',
'    v_html := v_html || ''<div>'';',
'',
'    FOR i IN 1 .. v_barcode_list.COUNT LOOP',
'        IF v_barcode_list(i) IS NOT NULL THEN',
'            ',
'            FOR rec IN (',
'                SELECT *',
'                FROM apps.Q_PACKING_LIST_FABRIC_ISSUE__V@proddb',
'                WHERE BAR_CODE_PL = v_barcode_list(i)',
'            ) LOOP',
'',
'                v_html := v_html || ''',
'                <div style="',
'                    border: 1px solid #ccc; ',
'                    border-radius: 8px; ',
'                    border-color: black;',
'                    padding: 10px; ',
'                    margin: 2px; ',
'                    width: 200px; ',
'                    font-family: Times New Roman, sans-serif; ',
'                    display: inline-block;',
'                    vertical-align: top;',
'                    background-color: #f9f9f9;">',
'',
'                    <div style="text-align:center; margin-bottom: 10px;">',
'                        <img src="https://bwipjs-api.metafloor.com/?bcid=code128&text=''|| rec.BAR_CODE_PL ||''&scale=2"',
'                             style="width:140px; max-height:30px;" />',
'                    </div>',
'',
'                    <b>Barcode:</b> ''|| rec.BAR_CODE_PL ||''<br>',
'                    <b>PlanID:</b> ''|| rec.PLAN_ID ||''&nbsp;&nbsp;<b>Pieces:</b> ''|| rec.NO_PIECES_PL ||'' <br>',
'                    <b>Plan:</b><br><span style=" text-align:bold; font-size:10.5px;">''|| rec.PLAN_NAME ||''</span><br> ',
'                    <b>Org:</b> ''|| rec.ORGANIZATION_NAME ||'' (''|| rec.ORGANIZATION_ID ||'')<br>',
'                    <b>Collection:</b> ''|| rec.COLLECTION_ID ||''<br>',
'                    <b>Occurrence:</b> ''|| rec.OCCURRENCE ||''<br>',
'                    <b>OGPNo:</b> ''|| rec.OGP_NO_PL ||''<br>',
'                    <b>OrderNo:</b> ''|| rec.ORDER_NO_PL ||''<br>',
'                    <b>JobNo:</b> ''|| rec.JOB_NO_PL ||''<br>',
'                    <b>PackNo:</b> ''|| rec.PACK_NO_PL ||''&nbsp;&nbsp;&nbsp;&nbsp;<b>Qty:</b> ''|| rec.QTY_PACK_PL ||''',
'                    ',
'                </div>',
'                '';',
'            END LOOP;',
'',
'        END IF;',
'    END LOOP;',
