'    .success{animation: successPulse 900ms ease forwards} @keyframes successPulse{0%{box-shadow:0 8px 30px rgba(79,204,255,0.06)}50%{box-shadow:0 12px 50px rgba(79,204,255,0.14)}100%{box-shadow:0 8px 30px rgba(79,204,255,0.06)}}',
'  </style>',
'</head>',
'<body>',
'  <div class="particles" aria-hidden="true"></div>',
'  <main class="wrap" role="main">',
'    <section class="card" aria-labelledby="loginTitle">',
'      <header class="brand">',
'        <div class="logo" aria-hidden="true">',
'          <svg viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">',
'            <rect x="6" y="6" width="36" height="36" rx="8" fill="url(#g)" />',
'            <path d="M14 30 L22 18 L34 30" stroke="#02112b" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" fill="none"/>',
'            <defs>',
'              <linearGradient id="g" x1="0" y1="0" x2="1" y2="1">',
'                <stop offset="0" stop-color="#6ea8ff" stop-opacity="0.95" />',
'                <stop offset="1" stop-color="#3b70ff" stop-opacity="0.95" />',
'              </linearGradient>',
'            </defs>',
'          </svg>',
'        </div>',
'        <div>',
'          <h1 id="loginTitle">Welcome back</h1>',
'          <p>Sign in to continue to your dashboard</p>',
'        </div>',
'      </header>',
'',
'      <form id="loginForm" autocomplete="on" aria-describedby="loginHelp">',
'        <div class="field">',
'          <input id="P1_USERNAME" type="text" name="P1_USERNAME" placeholder=" " required autocomplete="username" />',
'          <label for="P1_USERNAME" class="floater">Username or email</label>',
'        </div>',
'        <div class="field">',
'          <input id="P1_PASSWORD" type="password" name="P1_PASSWORD" placeholder=" " required autocomplete="current-password" />',
'          <label for="P1_PASSWORD" class="floater">Password</label>',
'        </div>',
'',
'        <div class="actions">',
'          <div class="left">',
'            <label class="checkbox"><input type="checkbox" id="remember" name="remember" /><span class="helper">Remember me</span></label>',
'          </div>',
'          <div>',
'            <a href="#" class="link">Forgot password?</a>',
'          </div>',
'        </div>',
'',
'        <div>',
'          <button type="button" class="btn" id="btnLogin">',
'            <svg width="16" height="16" viewBox="0 0 24 24" fill="none">',
'              <path d="M5 12h14" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>',
'              <path d="M12 5l7 7-7 7" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>',
'            </svg>',
'            <span>Sign in</span>',
'          </button>',
'        </div>',
'',
'        <div class="divider" role="separator" aria-hidden="true"></div>',
'        <p class="foot" id="loginHelp">Don''t have an account? <a href="#" class="link">Request access</a></p>',
'      </form>',
'    </section>',
'  </main>',
'',
'  <script>',
'    (function(){',
'      const btn = document.getElementById(''btnLogin'');',
'      btn.addEventListener(''click'', function(){',
'        const username = document.getElementById(''P1_USERNAME'').value;',
'        const password = document.getElementById(''P1_PASSWORD'').value;',
'        if(!username || !password){',
'          alert(''Please enter username and password'');',
'          return;',
'        }',
'',
'        // Set APEX hidden items',
'        $s(''P1_USERNAME'', username);',
'        $s(''P1_PASSWORD'', password);',
'',
'        // Submit page to APEX login process',
'        apex.submit(''LOGIN'');',
'      });',
'    })();',
'  </script>',
'</body>',
'</html>',
''))
,p_required_patch=>wwv_flow_imp.id(191724404433163656)
